record RegisterUserRequestDto(String email, String password) {}

List<String> validateFormat(RegisterUserRequestDto request) {
    List<String> errors = new ArrayList<>();
    if (request.email() == null || !request.email().contains("@")) {
        errors.add("Niepoprawny format email");
    }
    if (request.password() == null || request.password().length() < 8) {
        errors.add("Haslo musi miec co najmniej 8 znakow");
    }
    return errors; // pusta lista = format poprawny; BEZ zadnego zapytania do bazy danych
}

class User { // POZIOM 2: niezmiennik domenowy - w konstruktorze encji
    private final String email;
    private final int age;

    User(String email, int age) {
        if (age < 0) throw new IllegalArgumentException("Wiek nie moze byc ujemny");
        this.email = email;
        this.age = age;
    }
}

class UserRegistrationService { // POZIOM 3: regula biznesowa - wymaga repozytorium
    private final UserRepository repository;
    UserRegistrationService(UserRepository repository) { this.repository = repository; }

    void register(RegisterUserRequestDto request, int age) {
        if (repository.existsByEmail(request.email())) {
            throw new IllegalStateException("Ten email jest juz zajety");
        }
        User user = new User(request.email(), age); // niezmiennik sprawdzony w konstruktorze
        repository.save(user);
    }
}

// ZLE: kontroler sam sprawdza WSZYSTKIE 3 poziomy, wlacznie z dostepem do repozytorium
class RegisterControllerFat {
    private final UserRepository repository; // kontroler zna repozytorium BEZPOSREDNIO!

    RegisterControllerFat(UserRepository repository) { this.repository = repository; }

    String handleRegister(RegisterUserRequestDto request, int age) {
        if (!request.email().contains("@")) return "400: zly format";      // poziom 1
        if (age < 0) return "400: zly wiek";                                // poziom 2
        if (repository.existsByEmail(request.email())) return "409: zajety"; // poziom 3
        repository.save(new User(request.email(), age));
        return "201 Created";
    }
}

// DOBRZE: kontroler deleguje kazdy poziom do wlasciwego miejsca
class RegisterController {
    private final UserRegistrationService service; // NIE zna UserRepository bezposrednio

    RegisterController(UserRegistrationService service) { this.service = service; }

    String handleRegister(RegisterUserRequestDto request, int age) {
        List<String> formatErrors = validateFormat(request); // poziom 1 - osobna funkcja
        if (!formatErrors.isEmpty()) return "400: " + formatErrors;
        service.register(request, age); // poziomy 2 i 3 - wewnatrz Service/encji
        return "201 Created";
    }
}
